const antiCheatSystem = {
    navigationAttemptCount: 0,
    maxAttemptsBeforeAutoSubmit: 3,
    navigationPreventionActive: false,
    isNavigationLocked: false,
    warningMessages: [],
    activeWarningModal: null,
    activeWarningInterval: null,
    tabSwitchPending: false,
    handlers: {
        popstate: null,
        beforeunload: null,
        visibilitychange: null,
        contextmenu: null,
        keydown: null
    },

    init() {
        if (examStarted && !examSubmitted) {
            this.navigationPreventionActive = true;
            this.attachGlobalListeners();
            this.blockBrowserNavigation();
        }
    },

    attachGlobalListeners() {
        this.handlers.popstate = (e) => this.handleNavigationAttempt('محاولة التنقل إلى الخلف/الأمام');
        this.handlers.beforeunload = (e) => this.handleBeforeUnload(e);
        this.handlers.visibilitychange = () => this.handleVisibilityChange();

        window.addEventListener('popstate', this.handlers.popstate);
        window.addEventListener('beforeunload', this.handlers.beforeunload);
        document.addEventListener('visibilitychange', this.handlers.visibilitychange);
    },

    handleNavigationAttempt(source) {
        if (!examStarted || examSubmitted || !this.navigationPreventionActive) return;

        history.pushState(null, null, window.location.href);
        this.navigationAttemptCount++;

        const attemptsLeft = Math.max(0, this.maxAttemptsBeforeAutoSubmit - this.navigationAttemptCount);
        if (this.navigationAttemptCount >= this.maxAttemptsBeforeAutoSubmit) {
            this.autoSubmitExam('تم اكتشاف العديد من محاولات الغش');
            return;
        }

        this.showCheatWarningModal(source, attemptsLeft);
    },

    handleBeforeUnload(e) {
        if (!examStarted || examSubmitted || !this.navigationPreventionActive) return;

        e.preventDefault();
        e.returnValue = '';
        this.handleNavigationAttempt('تحديث الصفحة / إغلاق');
        return '';
    },

    handleVisibilityChange() {
        if (!examStarted || examSubmitted || !this.navigationPreventionActive) return;

        if (document.visibilityState === 'hidden') {
            this.navigationAttemptCount++;
            this.tabSwitchPending = true;
            if (this.navigationAttemptCount >= this.maxAttemptsBeforeAutoSubmit) {
                this.autoSubmitExam('تم اكتشاف العديد من محاولات تبديل التبويب');
            }
            return;
        }

        if (document.visibilityState === 'visible' && this.tabSwitchPending) {
            const attemptsLeft = Math.max(0, this.maxAttemptsBeforeAutoSubmit - this.navigationAttemptCount);
            this.showCheatWarningModal('تم تبديل التبويب. الرجاء العودة إلى نافذة الامتحان.', attemptsLeft);
            this.tabSwitchPending = false;
        }
    },

    showCheatWarningModal(message, attemptsLeft, countdownSeconds = 5) {
        if (!examStarted || examSubmitted || !this.navigationPreventionActive) return;
        if (this.activeWarningModal) return;

        const modalOverlay = document.createElement('div');
        modalOverlay.className = 'modal-overlay cheat-warning-modal';
        modalOverlay.innerHTML = `
            <div class="cheat-modal-content">
                <div class="cheat-icon">⚠️</div>
                <h2>تحذير: تم اكتشاف نشاط مشبوه</h2>
                <p class="cheat-message">${message}</p>
                <p class="cheat-message">محاولات متبقية: ${attemptsLeft}/${this.maxAttemptsBeforeAutoSubmit}</p>
                <div class="cheat-countdown">
                    <span id="warning-countdown">${countdownSeconds}</span>
                    <span>ثوانٍ متبقية</span>
                </div>
                <div class="cheat-progress">
                    <div class="cheat-progress-bar" id="warning-progress-bar"></div>
                </div>
            </div>
        `;

        document.body.appendChild(modalOverlay);
        modalOverlay.addEventListener('click', (e) => e.preventDefault());
        modalOverlay.addEventListener('keydown', (e) => e.preventDefault());
        modalOverlay.addEventListener('contextmenu', (e) => e.preventDefault());

        this.activeWarningModal = modalOverlay;
        let countdown = countdownSeconds;

        this.activeWarningInterval = setInterval(() => {
            countdown--;
            const countdownEl = modalOverlay.querySelector('#warning-countdown');
            const progressBar = modalOverlay.querySelector('#warning-progress-bar');

            if (countdownEl) countdownEl.textContent = String(countdown);
            if (progressBar) {
                const progress = ((countdownSeconds - countdown) / countdownSeconds) * 100;
                progressBar.style.width = `${progress}%`;
            }

            if (countdown <= 0) {
                this.clearActiveWarningModal();
            }
        }, 1000);
    },

    clearActiveWarningModal() {
        if (this.activeWarningInterval) {
            clearInterval(this.activeWarningInterval);
            this.activeWarningInterval = null;
        }
        if (this.activeWarningModal && this.activeWarningModal.parentNode) {
            this.activeWarningModal.remove();
        }
        this.activeWarningModal = null;
    },

    blockBrowserNavigation() {
        this.handlers.contextmenu = (e) => {
            if (examStarted && !examSubmitted) {
                e.preventDefault();
                return false;
            }
        };

        this.handlers.keydown = (e) => {
            if (!examStarted || examSubmitted) return;

            if ((e.altKey && e.key === 'ArrowLeft') || (e.key === 'Backspace' && e.target !== document.activeElement)) {
                e.preventDefault();
                this.handleNavigationAttempt('Backspace');
                return false;
            }

            if (e.key === 'F5') {
                e.preventDefault();
                this.handleNavigationAttempt('F5 (تحديث)');
                return false;
            }

            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'r') {
                e.preventDefault();
                this.handleNavigationAttempt('Ctrl+R (تحديث)');
                return false;
            }

            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'w') {
                e.preventDefault();
                this.handleNavigationAttempt('Ctrl+W (إغلاق التبويب)');
                return false;
            }
        };

        document.addEventListener('contextmenu', this.handlers.contextmenu);
        document.addEventListener('keydown', this.handlers.keydown);
    },

    autoSubmitExam(reason) {
        if (examSubmitted) {
            console.log('[ANTI-CHEAT] Auto-submit already initiated, skipping duplicate');
            return;
        }

        console.log(`[ANTI-CHEAT] Cheating detected: ${reason}`);
        this.clearActiveWarningModal();

        const modalOverlay = document.createElement('div');
        modalOverlay.className = 'modal-overlay cheat-detection-modal';
        modalOverlay.innerHTML = `
            <div class="cheat-modal-content">
                <div class="cheat-icon">❌</div>
                <h2>تم اكتشاف غش!</h2>
                <p class="cheat-message">${reason}</p>
                <p class="cheat-message">سيتم تسليم الامتحان تلقائياً خلال 10 ثوانٍ...</p>
                <div class="cheat-countdown">
                    <span id="countdown-timer">10</span>
                    <span>ثوانٍ متبقية</span>
                </div>
                <div class="cheat-progress">
                    <div class="cheat-progress-bar" id="progress-bar"></div>
                </div>
            </div>
        `;

        document.body.appendChild(modalOverlay);
        modalOverlay.addEventListener('click', (e) => e.preventDefault());
        modalOverlay.addEventListener('keydown', (e) => e.preventDefault());
        modalOverlay.addEventListener('contextmenu', (e) => e.preventDefault());

        this.navigationPreventionActive = false;

        let countdown = 10;
        const countdownEl = modalOverlay.querySelector('#countdown-timer');
        const progressBar = modalOverlay.querySelector('#progress-bar');

        const countdownInterval = setInterval(() => {
            countdown--;
            if (countdownEl) countdownEl.textContent = String(countdown);
            if (progressBar) {
                const progress = ((10 - countdown) / 10) * 100;
                progressBar.style.width = `${progress}%`;
            }

            if (countdown <= 0) {
                clearInterval(countdownInterval);
                this.performAutoSubmission(modalOverlay);
            }
        }, 1000);
    },

    async performAutoSubmission(modalOverlay) {
        try {
            await finishQuiz();
            setTimeout(() => {
                if (modalOverlay && modalOverlay.parentNode) {
                    modalOverlay.remove();
                }
                showScreen('results');
            }, 300);
        } catch (error) {
            showScreen('results');
            if (modalOverlay && modalOverlay.parentNode) {
                modalOverlay.remove();
            }
        }
    },

    disable() {
        this.navigationPreventionActive = false;
        this.navigationAttemptCount = 0;
        examSubmitted = true;
        this.clearActiveWarningModal();
    },

    cleanup() {
        if (this.handlers.popstate) {
            window.removeEventListener('popstate', this.handlers.popstate);
            this.handlers.popstate = null;
        }

        if (this.handlers.beforeunload) {
            window.removeEventListener('beforeunload', this.handlers.beforeunload);
            this.handlers.beforeunload = null;
        }

        if (this.handlers.visibilitychange) {
            document.removeEventListener('visibilitychange', this.handlers.visibilitychange);
            this.handlers.visibilitychange = null;
        }

        if (this.handlers.contextmenu) {
            document.removeEventListener('contextmenu', this.handlers.contextmenu);
            this.handlers.contextmenu = null;
        }

        if (this.handlers.keydown) {
            document.removeEventListener('keydown', this.handlers.keydown);
            this.handlers.keydown = null;
        }

        this.clearActiveWarningModal();
        this.reset();
    },

    reset() {
        this.navigationAttemptCount = 0;
        this.isNavigationLocked = false;
        this.navigationPreventionActive = false;
        this.warningMessages = [];
        this.tabSwitchPending = false;
    }
};

function startQuiz() {

    antiCheatSystem.reset();
    // === ADD THIS ===
    studentName = document.getElementById('studentName').value.trim();
    if (!studentName) {
        alert('يرجى إدخال اسمك!');
        return;
    }

    if (!selectedTopic) {
        alert('يرجى اختيار المادة')
        return;
    }

    const numQuestion = parseInt(numQuestionsInput.value)
    if (numQuestion < 5 || numQuestion > 40) {
        alert('يرجى إدخال عدد بين 5 و 40!');
        return;
    }

    // Get questions
    const topicQuestions = quizData[selectedTopic][selectedDifficulty];
    currentQuiz = [];

    while (currentQuiz.length < numQuestion && currentQuiz.length < topicQuestions.length) {
        const randomQuestion = topicQuestions[Math.floor(Math.random() * topicQuestions.length)];
        if (!currentQuiz.includes(randomQuestion)) {
            currentQuiz.push(randomQuestion);
        }
    }

    // Shuffle options ONLY once per question set
    currentQuiz = currentQuiz.map(q => {
        const shuffled = q.opts
            .map((option, index) => ({ option, originalIndex: index }))
            .sort(() => Math.random() - 0.5);

        return {
            ...q,
            shuffledOptions: shuffled
        };
    });

    currentQuestion = 0;
    score = 0;
    selectedAnswers = new Array(currentQuiz.length).fill(null);
    startTime = Date.now();

    // Start timer
    timeRemaining = currentQuiz.length * 40;
    startTimer();

    tabSwitchCount = 0;
    examStarted = true;
    examSubmitted = false;
    antiCheatSystem.init(); // Initialize anti-cheat protection
    showScreen('quiz');
    quitBtn.disabled = false;
    selectedClassDisplay.textContent = classMapping[selectedDifficulty] || 'JSS 2';
    displayQuestion();
    document.getElementById('studentNameDisplay').textContent = studentName;
}
function startTimer() {
    const timerEl = document.getElementById('timer');
    timerInterval = setInterval(() => {
        timeRemaining--;
        const minutes = Math.floor(timeRemaining / 60);
        const seconds = timeRemaining % 60;
        timerEl.textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

        if (timeRemaining <= 30) {
            timerEl.classList.add('warning');
        } else {
            timerEl.classList.remove('warning');
        }

        if (timeRemaining <= 0) {
            finishQuiz();
        }
    }, 1000);
}

function displayQuestion() {
    const question = currentQuiz[currentQuestion];

    document.getElementById('questionText').textContent = question.q;
    document.getElementById('currentQuestion').textContent = currentQuestion + 1;
    document.getElementById('totalQuestions').textContent = currentQuiz.length;
    updateProgressBar(currentQuestion + 1, currentQuiz.length);

    // Sync slider
    questionSlider.value = currentQuestion + 1;
    questionSlider.max = currentQuiz.length;

    // Update class display
    selectedClassDisplay.textContent = classMapping[selectedDifficulty] || 'JSS 2';

    const optionsContainer = document.getElementById('options');
    optionsContainer.innerHTML = '';

    const shuffledOptions = question.shuffledOptions;

    shuffledOptions.forEach(({ option, originalIndex }) => {
        const optionWrapper = document.createElement('label');
        optionWrapper.className = 'option';

        const radio = document.createElement('input');
        radio.type = 'radio';
        radio.name = 'answer';
        radio.value = originalIndex;

        if (selectedAnswers[currentQuestion] === originalIndex) {
            radio.checked = true;
            optionWrapper.classList.add('selected');
        }

        radio.addEventListener('change', () => {
            selectedAnswers[currentQuestion] = originalIndex;
            document.querySelectorAll('.option').forEach(opt => {
                opt.classList.remove('selected');
            });

            optionWrapper.classList.add('selected');

            // Show prompt if this is the last question
            if (currentQuestion === currentQuiz.length - 1) {
                setTimeout(() => {
                    alert('لقد أجبت على السؤال الأخير. انقر على "تسليم الاختبار" عند الاستعداد.');
                }, 500);
            }
        });

        const textSpan = document.createElement('span');
        textSpan.textContent = option;

        optionWrapper.appendChild(radio);
        optionWrapper.appendChild(textSpan);

        optionsContainer.appendChild(optionWrapper);
    });

    // Previous button control
    if (prevBtn) {
        prevBtn.disabled = currentQuestion === 0;
    }
}

function showTemporaryQuizMessage(message) {
    if (!quizMessageEl) return;
    quizMessageEl.textContent = message;
    clearTimeout(showTemporaryQuizMessage.timeoutId);
    showTemporaryQuizMessage.timeoutId = setTimeout(() => {
        quizMessageEl.textContent = '';
    }, 3500);
}

function nextQuestion() {
    if (currentQuestion < currentQuiz.length - 1) {
        currentQuestion++;
        displayQuestion();
    } else {
        showTemporaryQuizMessage('لقد وصلت إلى السؤال الأخير. استخدم زر تسليم الامتحان عندما تكون جاهزاً.');
    }
}

async function finishQuiz() {

    if (!examStarted && examSubmitted) {
        console.log('[FINISH-QUIZ] Already finalized');
        return;
    }
    // Prevent multiple submissions
    if (examSubmitted) {
        console.log('[FINISH-QUIZ] Already submitted, skipping duplicate');
        return;
    }
    examSubmitted = true;
    antiCheatSystem.disable();

    console.log('[FINISH-QUIZ] Quiz submission initiated');

    // Stop timer
    clearInterval(timerInterval);
    examStarted = false;

    // Calculate score
    calculateScore();
    console.log(`[FINISH-QUIZ] Score calculated: ${score}/${currentQuiz.length}`);

    // Map difficulty to class level
    const classMapping = {
        easy: 'JSS 1',
        medium: 'JSS 2',
        hard: 'JSS 3'
    };
    const classLevel = classMapping[selectedDifficulty] || 'JSS 2';

    // Save to Firebase and wait for completion
    try {
        console.log('[FINISH-QUIZ] Saving to Firebase...');
        await saveScoreToServer(studentName, score, classLevel, currentQuiz.length);
        console.log('[FINISH-QUIZ] Firebase save completed successfully');
    } catch (error) {
        console.error('[FINISH-QUIZ] Firebase save failed, showing results anyway:', error);
        // Continue to results screen even if Firebase fails
    }

    // Transition to results screen
    console.log('[FINISH-QUIZ] Transitioning to results screen');
    showScreen('results');

    antiCheatSystem.disable();
    antiCheatSystem.reset();
    antiCheatSystem.cleanup();

}

function calculateScore() {
    score = 0;
    selectedAnswers.forEach((answer, index) => {
        if (answer === currentQuiz[index].ans) {
            score++;
        }
    });

    const scaledScore = Math.round((score / currentQuiz.length) * 60);
    const percentage = Math.round((score / currentQuiz.length) * 100);
    const timeTaken = Math.floor((Date.now() - startTime) / 1000);
    const minutes = Math.floor(timeTaken / 60);
    const seconds = timeTaken % 60;

    let message = '';
    let passed = false;
    if (percentage === 100) {
        message = `🌟 Excellent Performance!<br>Grade: A (Distinction)`;
        passed = true;
    } else if (percentage >= 80) {
        message = `🎉 Very Good Performance.<br>Grade: A`;
        passed = true;
    } else if (percentage >= 70) {
        message = `👍 Good Performance.<br>Grade: B`;
        passed = true;
    } else if (percentage >= 60) {
        message = `✔ Fair Performance.<br>Grade: C`;
        passed = true;
    } else if (percentage >= 50) {
        message = `⚠ Pass.<br>Grade: D`;
        passed = true;
    } else {
        message = `❌ Fail.<br>Grade: F`;
        passed = false;
    }
    document.getElementById('finalScore').textContent = `${scaledScore}/60`;
    document.getElementById('scoreMessage').innerHTML = message;
    document.getElementById('correctCount').textContent = score;
    document.getElementById('wrongCount').textContent = currentQuiz.length - score;
    document.getElementById('percentage').textContent = `${percentage}%`;
    document.getElementById('timeTaken').textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    document.getElementById('topicResult').textContent = topicNames[selectedTopic] || selectedTopic.charAt(0).toUpperCase() + selectedTopic.slice(1);

    const classMapping = {
        easy: 'JSS 1',
        medium: 'JSS 2',
        hard: 'JSS 3'
    };
    document.getElementById('studentNameResult').textContent = studentName || 'N/A';
    document.getElementById('classResult').textContent = classMapping[selectedDifficulty] || 'JSS 2';

    // Play sound and show effect
    setTimeout(() => {
        if (passed) {
            launchConfetti();
            const passSound = document.getElementById('passSound');
            if (passSound) {
                passSound.pause();
                passSound.currentTime = 0;
                passSound.volume = 1;
                passSound.play().catch(() => { });
            }
        } else if (percentage < 50) {
            if (typeof launchFailEffect === 'function') launchFailEffect();
            const failSound = document.getElementById('failSound');
            if (failSound) {
                failSound.pause();
                failSound.currentTime = 0;
                failSound.volume = 1;
                failSound.play().catch(() => { });
            }
        }
    }, 100);
}

// === ADD THIS ===
function saveScoreToServer(name, score, classLevel, totalQuestions) {
    return new Promise((resolve, reject) => {
        // Check Firebase availability
        if (!window.db || !window.addDoc || !window.collection) {
            console.warn('[FIREBASE] Firebase not ready, storing locally');
            // Store locally as fallback
            const localScore = {
                name: name,
                class: classLevel,
                subject: selectedTopic,
                score: score,
                scoreOver60: Math.round((score / totalQuestions) * 60),
                percentage: Math.round((score / totalQuestions) * 100),
                totalQuestions: totalQuestions,
                timestamp: new Date().toISOString(),
                source: 'local'
            };
            localStorage.setItem(`quiz_score_${Date.now()}`, JSON.stringify(localScore));
            console.log('[FIREBASE] Score stored locally:', localScore);
            resolve(localScore);
            return;
        }

        const scoreOver60 = Math.round((score / totalQuestions) * 60);
        const percentage = Math.round((score / totalQuestions) * 100);

        const scoreData = {
            name: name,
            class: classLevel,
            subject: selectedTopic,
            score: score,
            scoreOver60: scoreOver60,
            percentage: percentage,
            totalQuestions: totalQuestions,
            timestamp: new Date()
        };

        console.log('[FIREBASE] Saving score data:', scoreData);

        window.addDoc(collection(db, 'cbt_scores_arabic'), scoreData)
            .then((docRef) => {
                console.log('✅ [FIREBASE] Score saved successfully with ID:', docRef.id);
                resolve(docRef);
            })
            .catch((error) => {
                console.error('❌ [FIREBASE] Error saving score:', error);
                // Fallback: save locally
                scoreData.timestamp = scoreData.timestamp.toISOString();
                scoreData.source = 'local_fallback';
                localStorage.setItem(`quiz_score_${Date.now()}`, JSON.stringify(scoreData));
                console.log('[FIREBASE] Fallback: Score stored locally due to Firebase error');
                // Resolve anyway to continue with results screen
                resolve(scoreData);
            });
    });
}
